def _identify_platform_nodes(
    boundary_face_nodes: np.ndarray,
    nearest_surface_face_id: np.ndarray,
    region_dependency_graph: RegionDependencyGraph,
) -> np.ndarray:
    """
    Retrouve les noeuds frontiere du TetMesh reposant sur le plateau, a
    partir de `RegionDependencyGraph.platform_contact_faces` (calcule par
    step3, seule etape qui connait la position du plateau).

    NE PAS deduire le plateau de la topologie du graphe ("regions sans arete
    entrante") : des que la segmentation ne produit qu'une seule region -
    cas de toute forme simple, cube compris - cette region unique est a la
    fois racine et couvre tout le modele, ce qui ancrerait la totalite de la
    surface a 0 au lieu de la seule base, et empecherait le champ de croitre.
    """
    if len(boundary_face_nodes) == 0:
        return np.zeros(0, dtype=np.int64)

    platform_faces = region_dependency_graph.platform_contact_faces
    if platform_faces is None:
        raise FieldSolverError(
            "RegionDependencyGraph.platform_contact_faces est absent : "
            "impossible d'ancrer le champ au plateau. Utilisez la sortie de "
            "pipeline/step3_segmentation.run(), ou desactivez explicitement "
            "l'ancrage via FieldSolverParams(enable_platform_anchor=False)."
        )

    is_platform_face = np.asarray(platform_faces, dtype=bool)[nearest_surface_face_id]
    if not np.any(is_platform_face):
        return np.zeros(0, dtype=np.int64)

    return np.unique(boundary_face_nodes[is_platform_face].ravel())

